import sys
from functools import lru_cache

def solve_dataset(n, m, matches):
    target = (n - 1) // 2
    wins = [0] * n
    played = [[False] * n for _ in range(n)]
    for x, y in matches:
        x -= 1
        y -= 1
        wins[x] += 1
        played[x][y] = played[y][x] = True

    need = [target - w for w in wins]
    if any(need[i] < 0 for i in range(n)):
        return 0

    # Build list of remaining edges
    edges = []
    deg_rem = [0] * n
    for i in range(n):
        for j in range(i + 1, n):
            if not played[i][j]:
                edges.append((i, j))
                deg_rem[i] += 1
                deg_rem[j] += 1

    if sum(need) != len(edges):
        return 0
    if any(need[i] > deg_rem[i] for i in range(n)):
        return 0

    # Precompute powers of 5
    pow5 = [1]
    for _ in range(1, n):
        pow5.append(pow5[-1] * 5)

    # Encode initial needs
    encoded_init = 0
    for i in range(n):
        encoded_init += need[i] * pow5[i]

    @lru_cache(maxsize=None)
    def dfs(idx, encoded):
        if idx == len(edges):
            return 1 if encoded == 0 else 0
        u, v = edges[idx]
        cnt = 0
        need_u = (encoded // pow5[u]) % 5
        if need_u > 0:
            cnt += dfs(idx + 1, encoded - pow5[u])
        need_v = (encoded // pow5[v]) % 5
        if need_v > 0:
            cnt += dfs(idx + 1, encoded - pow5[v])
        return cnt

    return dfs(0, encoded_init)


def main():
    data = sys.stdin.read().strip().split()
    it = iter(data)
    outputs = []
    for token in it:
        n = int(token)
        if n == 0:
            break
        m = int(next(it))
        matches = []
        for _ in range(m):
            x = int(next(it))
            y = int(next(it))
            matches.append((x, y))
        res = solve_dataset(n, m, matches)
        outputs.append(str(res))
    sys.stdout.write("\n".join(outputs))

if __name__ == "__main__":
    main()
