import sys
from collections import defaultdict

def compute_longest_palindrome_starting_at(s):
    n = len(s)
    if n == 0:
        return []
    P = [0] * n
    l, r = 0, -1
    for i in range(n):
        k = 0
        if i <= r:
            k = min(r - i, P[l + i - l])
        while i - k - 1 >= 0 and i + k < n and s[i - k - 1] == s[i + k]:
            k += 1
        P[i] = k
        if i + k - 1 > r:
            l = i - k
            r = i + k - 1
    events = []
    for c in range(n):
        L_bound = c - P[c]
        R_bound = c + P[c]
        events.append((L_bound, c + P[c], 'add'))
        events.append((R_bound + 1, c + P[c], 'remove'))
    events.sort(key=lambda x: x[0])
    heap = []
    removals = defaultdict(int)
    L_arr = [0] * n
    for i in range(n):
        while events and events[0][0] == i:
            pos, val, typ = events.pop(0)
            if typ == 'add':
                heapq.heappush(heap, -val)
            else:
                removals[val] += 1
        while heap and removals.get(-heap[0], 0) > 0:
            val = -heapq.heappop(heap)
            removals[val] -= 1
        if heap:
            max_val = -heap[0]
            L_arr[i] = max_val - i + 1
        else:
            L_arr[i] = 0
    return L_arr

def compute_longest_palindrome_ending_at(s):
    n = len(s)
    if n == 0:
        return []
    t = s[::-1]
    L_start = compute_longest_palindrome_starting_at(t)
    L_end = [0] * n
    for i in range(n):
        L_end[i] = L_start[n-1-i]
    return L_end

