    n = len(a)
    m = len(b)
    low, high = 1, min(n, m)
    k0 = 0
    while low <= high:
        mid = (low + high) // 2
        if find_common_substring(a, b, mid):
            k0 = mid
            low = mid + 1
        else:
            high = mid - 1
    return k0

def find_common_substring(a, b, k):
    if k <= 0:
