import sys

MOD = 10**9 + 7
INF = 10**18

class SegTree:
    def __init__(self, n, init_val):
        size = 1
        while size < n:
            size <<= 1
        self.size = size
        self.min = [INF] * (2 * size)
        self.lazy = [0] * (2 * size)
        # initialize leaves
        for i in range(n):
            self.min[size + i] = init_val
        # leaves beyond n are INF, internal nodes build
        for i in range(size - 1, 0, -1):
            self.min[i] = min(self.min[2 * i], self.min[2 * i + 1])

    def _apply(self, node, val):
        self.min[node] += val
        self.lazy[node] += val

    def _push(self, node):
        if self.lazy[node]:
            self._apply(node * 2, self.lazy[node])
            self._apply(node * 2 + 1, self.lazy[node])
            self.lazy[node] = 0

    def range_add(self, l, r, val):
        self._range_add(l, r, val, 1, 0, self.size - 1)

    def _range_add(self, l, r, val, node, nl, nr):
        if l > nr or r < nl:
            return
        if l <= nl and nr <= r:
            self._apply(node, val)
            return
        self._push(node)
        mid = (nl + nr) // 2
        self._range_add(l, r, val, node * 2, nl, mid)
        self._range_add(l, r, val, node * 2 + 1, mid + 1, nr)
        self.min[node] = min(self.min[node * 2], self.min[node * 2 + 1])

    def range_min(self, l, r):
        return self._range_min(l, r, 1, 0, self.size - 1)

    def _range_min(self, l, r, node, nl, nr):
        if l > nr or r < nl:
            return INF
        if l <= nl and nr <= r:
            return self.min[node]
        self._push(node)
        mid = (nl + nr) // 2
        return min(self._range_min(l, r, node * 2, nl, mid),
                   self._range_min(l, r, node * 2 + 1, mid + 1, nr))

def solve() -> None:
    data = list(map(int, sys.stdin.read().split()))
    it = iter(data)
    t = next(it)
    out_lines = []
    for _ in range(t):
        n = next(it)
        y = next(it)
        seg = SegTree(n, 1)
        for _ in range(y):
            l = next(it)
            r = next(it)
            mn = seg.range_min(l, r)
            seg.range_add(l, r, mn)
        final_min = seg.range_min(0, n - 1)
        out_lines.append(str(final_min % MOD))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
