				break
			i = i + 1
		n = n + 1
		even.append(2 * radius[i] + 1 - delta)
	even_odd = []
	for i in range(0, len(even)):
		even_odd.append(max(even[i], odd[i]))
	left = []
	right = []
	for i in range(1, len(even)):
		left.append(i - even_odd[i])
		right.append(i - 1)
	d = defaultdict(list)
	for i in range(0, len(left)):
