max_n = 100000

def build_spf(n):
    spf = list(range(n+1))
    for i in range(2, int(n**0.5) + 1):
        if spf[i] == i:
            for j in range(i*i, n+1, i):
                if spf[j] == j:
                    spf[j] = i
    return spf

spf = build_spf(max_n)

def main():
    import sys
    data = sys.stdin.read().splitlines()
    if not data:
        return
    n, m = map(int, data[0].split())

    state = [False] * (n + 1)
    count = [0] * (max_n + 1)
    rep = [0] * (max_n + 1)

    output_lines = []

    for i in range(1, m + 1):
        parts = data[i].split()
        op = parts[0]
        num = int(parts[1])

        if op == '+':
            if state[num]:
                output_lines.append("Already on")
            else:
                factors = []
                x = num
                if x > 1:
                    while x > 1:
                        p = spf[x]
                        factors.append(p)
                        while x % p == 0:
                            x //= p
                conflict = None
                for p in factors:
                    if count[p] > 0:
                        conflict = rep[p]
                        break
                if conflict is not None:
                    output_lines.append(f"Conflict with {conflict}")
                else:
                    state[num] = True
                    for p in factors:
                        count[p] += 1
                        rep[p] = num
                    output_lines.append("Success")
        else:
            if not state[num]:
                output_lines.append("Already off")
            else:
                state[num] = False
                x = num
                if x > 1:
                    while x > 1:
                        p = spf[x]
                        count[p] -= 1
                        while x % p == 0:
                            x //= p
                output_lines.append("Success")

    for line in output_lines:
        print(line)

if __name__ == "__main__":
    main()
